**The bug:** The condition uses strict less-than (`<`), so when `decoded.exp === Math.floor(Date.now() / 1000)` the check is `false` and the expired token passes. Per RFC 7519, a token must be rejected when `exp <= now`. The same flaw exists in `jwt.verify` itself for this edge case — it needs `clockTolerance: 0` plus the manual `<=` guard.

There are also two secondary issues: no differentiation between expired vs. malformed token errors, and no guard if `JWT_SECRET` is unset.

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  if (!process.env.JWT_SECRET) {
    console.error('JWT_SECRET is not configured');
    return res.status(500).json({ error: 'Server configuration error' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET, {
      clockTolerance: 0, // disable default leeway so exp boundary is exact
    });

    // Fix: <= rejects tokens expiring at exactly the current second (RFC 7519)
    // Math.floor avoids sub-second floating-point drift in Date.now() / 1000
    if (decoded.exp <= Math.floor(Date.now() / 1000)) {
      return res.status(401).json({ error: 'Token expired' });
    }

    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    console.error('Unexpected auth error:', err);
    return res.status(500).json({ error: 'Authentication failed' });
  }
}

module.exports = authMiddleware;
```

**Summary of changes:**

| Issue | Before | After |
|---|---|---|
| Off-by-one on expiry | `decoded.exp < now` | `decoded.exp <= Math.floor(now)` |
| jwt.verify clock leeway | default (1s tolerance) | `clockTolerance: 0` |
| Error granularity | single catch-all 401 | `TokenExpiredError` vs `JsonWebTokenError` vs 500 |
| Missing secret | silent undefined key | explicit 500 guard |
